create table public.hr_candidate_history (id uuid not null default gen_random_uuid(),candidate_id uuid not null,event_type text not null,from_status text,to_status text,note text,created_at timestamp with time zone not null default now(),PRIMARY KEY (id));
create table public.hr_candidates (id uuid not null default gen_random_uuid(),vacancy_id uuid not null,full_name text not null,whatsapp text not null,email text,municipality text,availability boolean,compensation_accepted boolean,start_availability text,experience_range text,relevant_areas text[] not null default '{}'::text[],tools text[] not null default '{}'::text[],excel_level text,driving_license boolean,external_errands boolean,transport_modes text[] not null default '{}'::text[],status text not null default 'new'::text,source text not null default 'public_form'::text,submitted_at timestamp with time zone not null default now(),decision_status text,decision_note text,profiled_target_role text,profiled_at timestamp with time zone,decision_updated_at timestamp with time zone,recruitment_cycle_id uuid,interview_availability_confirmed_at timestamp with time zone,internal_first_impression text,internal_role_fit text,internal_strengths text,internal_interview_checks text,internal_notes text,PRIMARY KEY (id),CHECK ((status = ANY (ARRAY['new'::text, 'reviewed'::text, 'preselected'::text, 'interview_scheduled'::text, 'interviewed'::text, 'selected'::text, 'not_selected'::text, 'hired'::text, 'archived'::text, 'trial'::text, 'talent_pool'::text]))));
create table public.hr_employees (id uuid not null default gen_random_uuid(),candidate_id uuid,role_id uuid,vacancy_id uuid,full_name text not null,email text,whatsapp text,role_title text,status text not null default 'active'::text,hired_at timestamp with time zone not null default now(),system_username text,system_auth_user_id uuid,system_roles jsonb not null default '[]'::jsonb,access_notes text,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now(),system_access_enabled boolean not null default false,UNIQUE (candidate_id),PRIMARY KEY (id),CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'on_leave'::text, 'terminated'::text]))));
create table public.hr_roles (id uuid not null default gen_random_uuid(),title text not null,area text,direct_manager text,description text,functions text,requirements text,schedule text,modality text,employment_type text,compensation text,location text,protocols text,training text,status text not null default 'active'::text,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now(),work_days text,recruitment_text text,recruitment_flyer_url text,application_form jsonb not null default '[]'::jsonb,automatic_replies jsonb not null default '{}'::jsonb,work_content jsonb not null default '{}'::jsonb,recruitment_responsibilities text,recruitment_requirements text,recruitment_contact_phone text,employment_contract_text text,employment_contract_path text,employment_contract_name text,employment_contract_mime text,employment_contract_uploaded_at timestamp with time zone,employment_contract_preview_path text,recruitment_contacts jsonb not null default '[]'::jsonb,subordinate_workers jsonb not null default '{"role_ids": [], "custom_text": ""}'::jsonb,payment_frequency text,payment_method text,currency text,trial_period text,training_period text,trial_compensation_different boolean not null default false,trial_compensation_amount text,training_compensation_different boolean not null default false,training_compensation_amount text,variable_income jsonb not null default '[]'::jsonb,extra_availability_required boolean not null default false,extra_availability_details text,department_id uuid,icon_code text not null default 'briefcase'::text,CHECK ((icon_code ~ '^[a-z0-9-]{2,40}$'::text)),PRIMARY KEY (id));
create table public.hr_trial_closure_events (id uuid not null default gen_random_uuid(),trial_id uuid not null,action text not null,payload jsonb not null default '{}'::jsonb,actor uuid default auth.uid(),created_at timestamp with time zone not null default now(),PRIMARY KEY (id));
create table public.hr_trial_closures (trial_id uuid not null,token_hash text not null,document_token_hash text not null,expires_at timestamp with time zone not null default (now() + '30 days'::interval),revoked_at timestamp with time zone,document jsonb not null,data jsonb not null default '{}'::jsonb,submitted_at timestamp with time zone,signed_received_at timestamp with time zone,verified_at timestamp with time zone,training_days integer,training_tutor text,training_start date,created_at timestamp with time zone not null default now(),UNIQUE (document_token_hash),PRIMARY KEY (trial_id),UNIQUE (token_hash),CHECK (((training_days >= 1) AND (training_days <= 365))));
create table public.hr_trial_periods (id uuid not null default gen_random_uuid(),candidate_id uuid not null,vacancy_id uuid,role_title text not null,start_date date,duration_days integer not null default 7,schedule text,compensation text,currency text default 'CUP'::text,location text,notes text,stage text not null default 'pending_agreement'::text,agreement_sent_at timestamp with time zone,agreement_accepted_at timestamp with time zone,trial_started_at timestamp with time zone,completed_at timestamp with time zone,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now(),agreement_url text,agreement_received_at timestamp with time zone,proposal_sent_at timestamp with time zone,UNIQUE (candidate_id),CHECK (((duration_days >= 1) AND (duration_days <= 90))),PRIMARY KEY (id),CHECK ((stage = ANY (ARRAY['pending_confirmation'::text, 'pending_agreement'::text, 'agreement_sent'::text, 'agreement_accepted'::text, 'in_trial'::text, 'evaluation_pending'::text, 'completed'::text]))));
create table public.hr_vacancies (id uuid not null default gen_random_uuid(),title text not null,slug text not null,description text,schedule text,compensation text,location_mode text default 'Presencial'::text,status text not null default 'draft'::text,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now(),recruitment_cycle_id uuid,PRIMARY KEY (id),UNIQUE (slug),CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'closed'::text, 'archived'::text]))));
CREATE OR REPLACE FUNCTION public.hr_prepare_trial_closure(p_trial uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.hr_trial_periods%rowtype; n text; tok text; doc text; d jsonb; tmpl jsonb; r_id uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(studio_access_private.is_owner(),false) THEN RAISE EXCEPTION 'No autorizado'; END IF;
 SELECT * INTO t FROM public.hr_trial_periods WHERE id=p_trial FOR UPDATE;
 IF NOT FOUND OR t.stage NOT IN ('in_trial','evaluation_pending') THEN RAISE EXCEPTION 'Prueba no disponible para cierre'; END IF;
 IF EXISTS(SELECT 1 FROM public.hr_trial_closures WHERE trial_id=p_trial) THEN RAISE EXCEPTION 'El cierre ya existe. Revisa el cierre guardado; no se sobrescribe.'; END IF;
 SELECT full_name INTO n FROM public.hr_candidates WHERE id=t.candidate_id;
 SELECT r.id, x.doc INTO r_id,tmpl FROM public.hr_roles r
 CROSS JOIN LATERAL jsonb_array_elements(coalesce(r.work_content->'contract_templates'->'trial'->'documents','[]'::jsonb)) x(doc)
 WHERE r.title=t.role_title AND x.doc->>'key'='trial_close'
 AND coalesce((r.work_content->'contract_templates'->'trial'->>'applies')::boolean,true)
 LIMIT 1;
 IF tmpl IS NULL THEN RAISE EXCEPTION 'La plaza no tiene configurada el Acta de Cierre del Período de Prueba en Contratación'; END IF;
 tok:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
 doc:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
 d:=jsonb_build_object('full_name',n,'role_title',t.role_title,'role_id',r_id,'start_date',t.start_date,'duration_days',t.duration_days,'closed_on',current_date,'template',tmpl);
 INSERT INTO public.hr_trial_closures(trial_id,token_hash,document_token_hash,document)
 VALUES(p_trial,encode(sha256(convert_to(tok,'UTF8')),'hex'),encode(sha256(convert_to(doc,'UTF8')),'hex'),d);
 INSERT INTO public.hr_trial_closure_events(trial_id,action,payload)
 VALUES(p_trial,'closure_prepared',jsonb_build_object('form_url','https://gestion.elcartelstudio.com/actualizar-expediente.html#token='||tok,'document_url','https://gestion.elcartelstudio.com/cierre-periodo-prueba.html#token='||doc,'role_id',r_id,'template_key','trial_close'));
 RETURN jsonb_build_object('form_url','https://gestion.elcartelstudio.com/actualizar-expediente.html#token='||tok,'document_url','https://gestion.elcartelstudio.com/cierre-periodo-prueba.html#token='||doc,'full_name',n);
END $function$

